def safe_filename(name, maxlen=80):
    name = re.sub(r"[\r\n\t]+", " ", name).strip()
    name = re.sub(r"\s*#\s*$", "", name)
    name = name.replace("/", "").replace("\\", "").replace("\0", "")
    if len(name) > maxlen:
