import math

def parse_pages(spec, total):
    if not spec or str(spec).lower() == 'all':
        return list(range(total))
    pages = set()
    for part in str(spec).split(','):
        part = part.strip()
        if not part:
            continue
        if '-' in part:
            start, end = part.split('-', 1)
            start = int(start) if start.strip() else 1
            end = int(end) if end.strip() else total
            start = max(1, start)
            end = min(total, end)
            if start <= end:
                pages.update(range(start, end + 1))
        else:
            page = int(part)
            if 1 <= page <= total:
                pages.add(page)
    return sorted(i - 1 for i in pages)"
}

